## 1) Modelo recomendado en TypeScript

```ts
export type MedicationClassId =
  | 'PDE5_INHIBITOR'
  | 'NITRATE'
  | 'NO_DONOR'
  | 'THIAZIDE_DIURETIC'
  | 'POTASSIUM_SPARING_DIURETIC'
  | 'BETA_BLOCKER'
  | 'CENTRAL_ANTIHYPERTENSIVE'
  | 'SSRI_ANTIDEPRESSANT'
  | 'TRICYCLIC_ANTIDEPRESSANT'
  | 'ANTIPSYCHOTIC'
  | 'ANTIANDROGEN'
  | 'H2_BLOCKER'
  | 'ALCOHOL'
  | 'NICOTINE'
  | 'CANNABIS'
  | 'COCAINE_OR_AMPHETAMINE'
  | 'OPIOID'
  | 'INTRACAVERNOUS_VASODILATOR'
  | 'VACUUM_DEVICE';

export type RuleSeverity =
  | 'info'
  | 'low'
  | 'moderate'
  | 'high'
  | 'critical';

export type RuleActionType =
  | 'info'
  | 'caution'
  | 'clinician-review'
  | 'hard-block'
  | 'medical-referral'
  | 'emergency-advice';

export interface MedicationInteractionTrigger {
  anyUserMedicationClass: MedicationClassId[];
  andAnyCoAdministeredClass: MedicationClassId[];
  includeRecreationalSubstances?: boolean;
  includePrnMedications?: boolean;
  includeFutureOrAsNeeded?: boolean;
}

export interface MedicationInteractionAction {
  appBehavior: RuleActionType;
  allowOverride: boolean;
  requireClinicianReview: boolean;
  blockFeatures?: string[];
  emergencyGuidance?: string;
}

export interface MedicationInteractionRule {
  id: string;
  type: 'medication-interaction';
  name: string;
  description: string;
  severity: RuleSeverity;
  trigger: MedicationInteractionTrigger;
  action: MedicationInteractionAction;
  userFacingMessage: {
    es: string;
    en?: string;
  };
  source: {
    bookId: string;
    chapter?: string;
    section?: string;
    appendix?: string;
    page?: string | null;
    notes?: string;
  };
  safetyNotes?: string[];
}
```

